function solve(deadends, target) {
  const dead = new Set();
  for (const d of deadends) {
    if (typeof d === 'string' && /^[0-9]{4}$/.test(d)) dead.add(d);
  }
  if (typeof target !== 'string' || !/^[0-9]{4}$/.test(target)) return -1;
  const start = '0000';
  if (dead.has(start) || dead.has(target)) return -1;
  if (start === target) return 0;
  const neighbors = (s) => {
    const out = [];
    for (let p = 0; p < 4; p++) {
      const dig = s.charCodeAt(p) - 48;
      out.push(s.slice(0, p) + String((dig + 1) % 10) + s.slice(p + 1));
      out.push(s.slice(0, p) + String((dig + 9) % 10) + s.slice(p + 1));
    }
    return out;
  };
  const distA = new Map();
  const distB = new Map();
  distA.set(start, 0);
  distB.set(target, 0);
  let frontA = [start];
  let frontB = [target];
  while (frontA.length > 0 && frontB.length > 0) {
    const expandA = frontA.length <= frontB.length;
    const front = expandA ? frontA : frontB;
    const own = expandA ? distA : distB;
    const other = expandA ? distB : distA;
    const next = [];
    let best = -1;
    for (const cur of front) {
      const d = own.get(cur);
      for (const nb of neighbors(cur)) {
        if (dead.has(nb) || own.has(nb)) continue;
        own.set(nb, d + 1);
        next.push(nb);
        if (other.has(nb)) {
          const total = d + 1 + other.get(nb);
          if (best === -1 || total < best) best = total;
        }
      }
    }
    if (best !== -1) return best;
    if (expandA) frontA = next;
    else frontB = next;
  }
  return -1;
}
